    for(i=0;i<18;i+=2){bfEnc(lr,p,s0,s1,s2,s3);p[i]=lr[0];p[i+1]=lr[1];}
    for(b=0;b<256;b+=2){bfEnc(lr,p,s0,s1,s2,s3);s0[b]=lr[0];s0[b+1]=lr[1];}
