    for(b=0;b<256;b+=2){bfEnc(lr,p,s0,s1,s2,s3);s2[b]=lr[0];s2[b+1]=lr[1];}
    for(b=0;b<256;b+=2){bfEnc(lr,p,s0,s1,s2,s3);s3[b]=lr[0];s3[b+1]=lr[1];}
